function emptyTeam(i) {
  return {
    id: `team-${Date.now()}-${i}`,
    name: `Team ${i + 1}`,
    captain: "",
    founded: "",
    crestColor: CREST_COLORS[i % CREST_COLORS.length],
    crest: null,
    tagline: "",
    bio: "",
    history: "",
    trophies: [],
  };
}

// A club is active unless explicitly retired, or still sitting on a placeholder name.
// Without this, any render error tears the whole app down and it remounts on the default
// tab — which looks like being mysteriously "sent back to the squad list". Catch it and
// show what actually happened instead.
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { error: null };
  }
  static getDerivedStateFromError(error) {
    return { error };
  }
  componentDidCatch(error, info) {
    console.error("Corner Kikudes error:", error, info);
  }
  render() {
    if (this.state.error) {
      return (
        <div style={{ background: TOKENS.surface, borderColor: TOKENS.danger }} className="border rounded-sm p-5">
          <h3 style={{ ...headingStyle, color: TOKENS.danger, fontSize: "0.9rem" }} className="mb-2">
            Something broke on this screen
          </h3>
          <p style={{ color: TOKENS.ink }} className="text-sm mb-1">
            {String(this.state.error?.message || this.state.error)}
          </p>
          <p style={{ color: TOKENS.muted }} className="text-xs mb-3">
            Nothing was lost — your data is saved. Send me this message and I'll fix it.
          </p>
          <button
            onClick={() => this.setState({ error: null })}
            style={{ background: TOKENS.gold, color: TOKENS.onGold }}
            className="text-xs font-bold uppercase tracking-wide px-3 py-2 rounded"
          >
            Try again
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

