// Positions, coloured so a roster reads at a glance.
const POSITIONS = {
  GK:  { label: "GK",  full: "Arquero",     color: "#C79A0A", bg: "#FBF0CC" },
  DEF: { label: "DEF", full: "Defensa",     color: "#1E7A46", bg: "#D8F0E2" },
  MID: { label: "MID", full: "Mediocampo",  color: "#1B5FA8", bg: "#D9E7F8" },
  FWD: { label: "FWD", full: "Delantero",   color: "#C0392B", bg: "#F9DED9" },
};
const POSITION_ORDER = ["GK", "DEF", "MID", "FWD"];

// Emparejar nombres entre el draft y los traspasos es más delicado de lo que parece: el
// draft tiene lo que se escribió en su momento y el traspaso lo que sugirió el
// autocompletado. "Théo Hernandez" y "Theo Hernandez", o "L. Figo" y "Luis Figo", son la
// misma persona y tienen que reconocerse como tal.
function playerKey(n) {
  return (n || "")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")   // sin acentos
    .toLowerCase()
    .replace(/[.'`´]/g, "")                              // sin puntos ni apóstrofos
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const POS_INDEX = (() => {
  const m = {};
  PLAYER_DB.forEach((p) => { if (p.p) m[p.n.toLowerCase()] = p.p; });
  return m;
})();

// Se permite texto libre en todas partes, así que un nombre desconocido no tiene posición.
// El índice se consulta primero exacto y luego de forma tolerante, porque en el draft es
// habitual haber escrito sólo el apellido ("Lampard" por "Frank Lampard").
const POS_BY_SURNAME = (() => {
  const m = {};
  PLAYER_DB.forEach((p) => {
    if (!p.p) return;
    const parts = playerKey(p.n).split(" ").filter(Boolean);
    const surname = parts[parts.length - 1];
    if (!surname) return;
    // si dos jugadores comparten apellido y posición distinta, no se puede decidir: se marca
    if (m[surname] && m[surname] !== p.p) m[surname] = "__ambiguo__";
    else if (!m[surname]) m[surname] = p.p;
  });
  return m;
})();

function positionOf(name) {
  const exact = POS_INDEX[(name || "").trim().toLowerCase()];
  if (exact) return exact;
  const parts = playerKey(name).split(" ").filter(Boolean);
  if (parts.length === 0) return null;
  const hit = POS_BY_SURNAME[parts[parts.length - 1]];
  return hit && hit !== "__ambiguo__" ? hit : null;
}

function PosTag({ pos, size = "md" }) {
  const p = POSITIONS[pos];
  if (!p) return null;
  const small = size === "sm";
  return (
    <span title={p.full}
          style={{ background: p.bg, color: p.color, borderColor: `${p.color}55`,
                   ...headingStyle, fontSize: small ? "0.5rem" : "0.55rem" }}
          className={`border rounded-sm shrink-0 ${small ? "px-1" : "px-1.5"} py-0.5`}>
      {p.label}
    </span>
  );
}

const PLAYER_INDEX = PLAYER_DB.map((p) => ({ ...p, key: p.n.toLowerCase() }));

function suggestPlayers(query, club, limit = 8) {
  const q = (query || "").trim().toLowerCase();
  const scored = PLAYER_INDEX.map((p) => {
    let s = 0;
    if (q) {
      // Order matters: a surname match must be tested before a loose substring match,
      // otherwise "mes" scores Lionel Messi as a mere substring and Mesut Ozil outranks him.
      const words = p.key.split(" ");
      if (p.key === q) s = 1000;
      else if (words.some((w) => w === q)) s = 900;
      else if (p.key.startsWith(q) || words.some((w) => w.startsWith(q))) s = 500;
      else if (p.key.includes(q)) s = 200;
      else return null;
    }
    // players this club actually fields come first; catalogue entries (never seen in a
    // match) still show, but below anyone with real history
    const forClub = club ? (p.c.find((x) => x[0] === club) || [null, 0])[1] : 0;
    const seen = p.a > 0 ? 4 : 0;
    return { ...p, score: s + seen + Math.min(forClub, 60) * 2 + Math.min(p.a, 200) / 50 };
  }).filter(Boolean);
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, limit);
}

// A text field that suggests players but never insists on one.
function PlayerInput({ value, onChange, club, placeholder, style, className, compact }) {
  const [open, setOpen] = useState(false);
  const [hi, setHi] = useState(0);
  const [pos, setPos] = useState(null);
  const boxRef = useRef(null);
  const inputRef = useRef(null);
  const sugg = open ? suggestPlayers(value, club, compact ? 6 : 8) : [];

  // Measure the input in viewport coordinates so the list can be position:fixed and escape
  // the scrolling table it lives in. Flips above the field when there's no room below.
  function place() {
    const el = inputRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const rowH = 30, pad = 26;
    const wanted = Math.min(sugg.length || 6, compact ? 6 : 8) * rowH + pad;
    const below = window.innerHeight - r.bottom;
    const up = below < wanted && r.top > below;
    setPos({ left: r.left, top: up ? undefined : r.bottom + 2,
             bottom: up ? window.innerHeight - r.top + 2 : undefined,
             width: Math.max(r.width, 210), maxHeight: Math.max(120, (up ? r.top : below) - 12) });
  }

  useEffect(() => {
    if (!open) return;
    place();
    const onMove = () => place();
    window.addEventListener("scroll", onMove, true);
    window.addEventListener("resize", onMove);
    return () => {
      window.removeEventListener("scroll", onMove, true);
      window.removeEventListener("resize", onMove);
    };
  }, [open, value]);

  useEffect(() => {
    function away(e) {
      if (boxRef.current && !boxRef.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", away);
    return () => document.removeEventListener("mousedown", away);
  }, []);

  function pick(name) {
    onChange(name);
    setOpen(false);
  }

  return (
    <div ref={boxRef} className="relative" style={{ minWidth: 0 }}>
      <input
        ref={inputRef}
        value={value ?? ""}
        onChange={(e) => { onChange(e.target.value); setOpen(true); setHi(0); }}
        onFocus={() => { setOpen(true); setTimeout(place, 0); }}
        onKeyDown={(e) => {
          if (!open || sugg.length === 0) return;
          if (e.key === "ArrowDown") { e.preventDefault(); setHi((h) => Math.min(h + 1, sugg.length - 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setHi((h) => Math.max(h - 1, 0)); }
          else if (e.key === "Enter") { e.preventDefault(); pick(sugg[hi].n); }
          else if (e.key === "Escape") setOpen(false);
        }}
        placeholder={placeholder}
        style={style}
        className={className}
      />
      {open && sugg.length > 0 && pos && (
        <div style={{ background: TOKENS.surface, borderColor: TOKENS.line, position: "fixed",
                      left: pos.left, top: pos.top, bottom: pos.bottom,
                      width: pos.width, maxHeight: pos.maxHeight, zIndex: 60 }}
             className="border rounded-sm overflow-y-auto shadow-lg">
          {sugg.map((p, i) => {
            const forClub = club ? (p.c.find((x) => x[0] === club) || [null, 0])[1] : 0;
            return (
              <button
                key={p.n}
                onMouseDown={(e) => { e.preventDefault(); pick(p.n); }}
                onMouseEnter={() => setHi(i)}
                style={{ background: i === hi ? `${TOKENS.gold}22` : "transparent" }}
                className="w-full text-left px-2 py-1.5 flex items-center gap-2"
              >
                <PosTag pos={p.p} size="sm" />
                <span style={{ ...headingStyle, fontSize: "0.68rem" }} className="truncate flex-1">{p.n}</span>
                <span style={{ color: TOKENS.muted, fontSize: "0.55rem" }} className="shrink-0">
                  {p.a === 0
                    ? "no matches yet"
                    : `${forClub > 0 ? `${forClub}× here · ` : ""}avg ${p.r.toFixed(2)}`}
                </span>
              </button>
            );
          })}
          <div style={{ color: TOKENS.muted, fontSize: "0.5rem", borderTop: `1px solid ${TOKENS.line}` }}
               className="px-2 py-1">
            or just type any name
          </div>
        </div>
      )}
    </div>
  );
}


// Squad views, derived from the same scan. c is [club, times fielded], so both directions
// (a club's players, a player's clubs) come from one list.
function squadFor(clubName) {
  const key = (clubName || "").trim().toLowerCase();
  return PLAYER_DB
    .map((p) => {
      const hit = p.c.find((x) => x[0].trim().toLowerCase() === key);
      // rHere / mHere son los de este club; r y m siguen siendo los globales
      return hit ? { ...p, forClub: hit[1], rHere: hit[2], mHere: hit[3] } : null;
    })
    .filter(Boolean)
    .sort((a, b) => b.forClub - a.forClub || b.a - a.a);
}

function clubsWithSquads() {
  const set = new Set();
  PLAYER_DB.forEach((p) => p.c.forEach((x) => set.add(x[0])));
  return [...set].sort();
}

function isActiveTeam(team) {
  if (!team) return false;
  if (/^Team \d+$/.test((team.name || "").trim())) return false;
  return team.active !== false;
}

function initials(name) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "??";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
}

// El almacenamiento del artefacto limita las llamadas por segundo ("Message rate limit
// exceeded"). Dos defensas: las llamadas van en fila con un pequeño espacio entre ellas, y
// si aun así el límite salta, se espera y se reintenta. Y una regla que no se negocia: un
// error de lectura NUNCA se disfraza de "no había nada", porque el guardado siguiente
// escribiría encima y borraría lo que había.
const STORAGE_GAP_MS = 35;
let _storageChain = Promise.resolve();
let _storageLast = 0;
function storageCall(fn) {
  const run = async () => {
    const wait = STORAGE_GAP_MS - (Date.now() - _storageLast);
    if (wait > 0) await new Promise((r) => setTimeout(r, wait));
    _storageLast = Date.now();
    return fn();
  };
  const p = _storageChain.then(run, run);
  _storageChain = p.catch(() => {});
  return p;
}
const isRateLimit = (e) => /rate limit|too many|try again|busy/i.test(String(e?.message || e || ""));
async function withRetry(fn, label) {
  const delays = [500, 1000, 2000, 4000];
  for (let i = 0; ; i++) {
    try { return await storageCall(fn); }
    catch (e) {
      if (!isRateLimit(e) || i >= delays.length) throw e;
      await new Promise((r) => setTimeout(r, delays[i]));
    }
  }
}
class StorageError extends Error {}

async function loadKey(key, fallback, shared = true) {
  try {
    const res = await withRetry(() => window.storage.get(key, shared), key);
    if (res && res.value !== undefined && res.value !== null) return JSON.parse(res.value);
    return fallback;
  } catch (e) {
    // una clave que no existe es un caso normal; el límite de tasa agotado, no: ése se
    // propaga para que nadie escriba sobre datos que no llegó a leer
    if (isRateLimit(e)) throw new StorageError("El almacenamiento está saturado. Espera unos segundos y prueba otra vez; si sigue pasando, recarga la página.");
    return fallback;
  }
}

async function saveKey(key, value, shared = true) {
  try {
    await withRetry(() => window.storage.set(key, JSON.stringify(value), shared), key);
    return true;
  } catch (e) {
    console.error("storage save failed", key, e);
    return false;
  }
}

