// Superlativos que dependen del plantel, no de los resultados.
const SQUAD_SUPERLATIVES = [
  { id: "topMvp",     label: "Casa del MVP",      tone: "gold",   icon: "star",
    desc: (v) => `${v.who} con ${v.n} MVPs aquí` },
  { id: "topRating",  label: "Mejor Nota",        tone: "teal",   icon: "star",
    desc: (v) => `${v.who} promedia ${v.n.toFixed(2)}` },
  { id: "mvpTotal",   label: "Fábrica de MVPs",   tone: "gold",   icon: "trophy",
    desc: (v) => `${v.n} MVPs entre todo el plantel` },
  { id: "deepSquad",  label: "Cantera Profunda",  tone: "teal",   icon: "shield",
    desc: (v) => `${v.n} jugadores distintos utilizados` },
  { id: "loyalCore",  label: "Once de Memoria",   tone: "slate",  icon: "shield",
    desc: (v) => `Sólo ${v.n} jugadores distintos — siempre los mismos` },
  { id: "squadAvg",   label: "Plantel de Lujo",   tone: "teal",   icon: "chart",
    desc: (v) => `Nota media del plantel: ${v.n.toFixed(2)}` },
];

// Devuelve un mapa club -> lista de medallas ganadas.
function leagueSuperlatives(matches, clubs) {
  const awarded = {};
  clubs.forEach((c) => (awarded[c] = []));
  if (matches.length === 0) return awarded;

  const recs = {};
  clubs.forEach((c) => (recs[c] = teamRecord(matches, c)));

  SUPERLATIVES.forEach((s) => {
    const elig = clubs.filter((c) => recs[c].pj > 0 && s.min(recs[c]));
    if (elig.length < 2) return;                       // sin competencia no hay mérito
    let best = null, bestV = -Infinity;
    elig.forEach((c) => {
      const v = s.of(recs[c]);
      if (v > bestV) { bestV = v; best = c; }
    });
    if (!best || bestV <= -Infinity) return;
    const shown = s.show ? s.show(recs[best]) : bestV;
    awarded[best].push({
      id: `sup-${s.id}`, label: s.label, tone: s.tone, icon: s.icon,
      desc: s.desc(shown, recs[best]),
    });
  });

  // --- plantel
  const squads = {};
  clubs.forEach((c) => (squads[c] = squadFor(c).filter((p) => p.forClub >= 4)));

  const pick = (id, valueOf) => {
    let best = null, bestV = null;
    clubs.forEach((c) => {
      const v = valueOf(squads[c], c);
      if (v && (bestV === null || v.n > bestV.n)) { bestV = v; best = c; }
    });
    if (!best || !bestV) return;
    const def = SQUAD_SUPERLATIVES.find((s) => s.id === id);
    awarded[best].push({ id: `sup-${id}`, label: def.label, tone: def.tone, icon: def.icon,
                         desc: def.desc(bestV) });
  };

  pick("topMvp", (sq) => {
    const top = sq.slice().sort((a, b) => (b.mHere || 0) - (a.mHere || 0))[0];
    return top && top.mHere > 0 ? { who: top.n, n: top.mHere } : null;
  });
  pick("topRating", (sq) => {
    const elig = sq.filter((p) => p.forClub >= 10);
    const top = elig.sort((a, b) => (b.rHere || 0) - (a.rHere || 0))[0];
    return top ? { who: top.n, n: top.rHere } : null;
  });
  pick("mvpTotal", (sq) => {
    const n = sq.reduce((a, p) => a + (p.mHere || 0), 0);
    return n > 0 ? { n } : null;
  });
  pick("deepSquad", (sq) => (sq.length ? { n: sq.length } : null));
  pick("squadAvg", (sq) => {
    const elig = sq.filter((p) => p.forClub >= 8);
    if (elig.length < 5) return null;
    const apps = elig.reduce((a, p) => a + p.forClub, 0);
    return { n: elig.reduce((a, p) => a + p.rHere * p.forClub, 0) / apps };
  });
  // este premia al más bajo, así que se invierte
  (() => {
    let best = null, bestN = Infinity;
    clubs.forEach((c) => {
      const n = squads[c].length;
      if (n >= 8 && n < bestN) { bestN = n; best = c; }
    });
    if (!best) return;
    const def = SQUAD_SUPERLATIVES.find((s) => s.id === "loyalCore");
    awarded[best].push({ id: "sup-loyalCore", label: def.label, tone: def.tone, icon: def.icon,
                         desc: def.desc({ n: bestN }) });
  })();


  // Una medalla por línea del campo: casi siempre reparte entre clubes distintos.
  const LINE_AWARDS = [
    ["GK",  "Guantes de Oro", "gold",  "Mejor portero"],
    ["DEF", "El Muro",        "navy",  "Mejor defensa"],
    ["MID", "El Cerebro",     "teal",  "Mejor mediocampista"],
    ["FWD", "El Killer",      "red",   "Mejor delantero"],
  ];
  LINE_AWARDS.forEach(([pos, label, tone, what]) => {
    let best = null, bestP = null;
    clubs.forEach((c) => {
      squads[c].filter((p) => p.p === pos && p.forClub >= 8).forEach((p) => {
        if (!bestP || p.rHere > bestP.rHere) { bestP = p; best = c; }
      });
    });
    if (!best) return;
    awarded[best].push({
      id: `sup-line-${pos}`, label, tone, icon: pos === "GK" ? "shield" : pos === "FWD" ? "flame" : "star",
      desc: `${what} de la liga: ${bestP.n} (${bestP.rHere.toFixed(2)})`,
    });
  });

  // Fetiche: el club que más ha confiado en un solo jugador.
  (() => {
    let best = null, bestP = null;
    clubs.forEach((c) => {
      const top = squads[c].slice().sort((a, b) => b.forClub - a.forClub)[0];
      if (top && (!bestP || top.forClub > bestP.forClub)) { bestP = top; best = c; }
    });
    if (!best) return;
    awarded[best].push({
      id: "sup-fetish", label: "Jugador Fetiche", tone: "bronze", icon: "star",
      desc: `${bestP.n} en ${bestP.forClub} partidos`,
    });
  })();

  // Especialistas: a quién se le da mejor cada formato.
  [["league", "Animal de Liga", "accent"], ["wb", "Bestia de Torneo", "gold"],
   ["lb", "Rey de la Remontada", "red"]].forEach(([phase, label, tone]) => {
    const sub = matches.filter((m) => m.phase === phase);
    if (sub.length < 10) return;
    let best = null, bestV = -Infinity;
    clubs.forEach((c) => {
      const r = teamRecord(sub, c);
      if (r.pj < 4) return;
      if (r.winPct > bestV) { bestV = r.winPct; best = c; }
    });
    if (!best) return;
    awarded[best].push({
      id: `sup-phase-${phase}`, label,
      tone: tone === "accent" ? "teal" : tone, icon: "chart",
      desc: `${Math.round(bestV)}% de victorias en ${phase === "league" ? "la liga" :
             phase === "wb" ? "el cuadro de ganadores" : "el cuadro de perdedores"}`,
    });
  });

  return awarded;
}

function computeBadges(teamName, team, tournaments, matches, supers) {
  const out = [];
  (supers || []).forEach((b) => out.push(b));
  const key = (teamName || "").trim().toLowerCase();
  const push = (b) => out.push(b);

  // --- standing
  if (has(teamName, OG_CLUBS)) {
    push({ id: "og", label: "OG", icon: "star", og: true,
           desc: "Uno de los tres clubes originales de Corner Kikudes" });
  }
  if (has(teamName, FOUNDING_MEMBERS)) {
    push({ id: "founder", label: "Miembro Fundador", tone: "gold", icon: "star",
           desc: "Uno de los clubes que empezaron Corner Kikudes" });
  }
  if (CURRENT_PRESIDENT.trim().toLowerCase() === key) {
    push({ id: "president", label: "Presidente", tone: "navy", icon: "shield",
           desc: "Dirige la liga actualmente" });
  } else if (has(teamName, PRESIDENTS)) {
    push({ id: "expresident", label: "Ex Presidente", tone: "slate", icon: "shield",
           desc: "Dirigió la liga en su momento" });
  }
  if (team && team.active === false) {
    push({ id: "dormant", label: "Inactivo", tone: "slate", icon: "moon",
           desc: "No compite por ahora" });
  }

  const honours = earnedHonours(tournaments, teamName);
  const titles = honours.tournamentPlaces.filter((p) => p.place === 1).length;
  const podiums = honours.tournamentPlaces.length;
  const seasonGolds = honours.seasonPlaces.filter((s) => s.place === 1 && !s.provisional).length;
  const summit = powerSummits(tournaments, teamName);
  const rec = teamRecord(matches, teamName);

  // --- earned
  const phases = phaseWinTotals(tournaments, teamName);
  if (phases.group > 0) {
    push({ id: "groupking", label: phases.group === 1 ? "Ganó un grupo" : `Reyes del Grupo ×${phases.group}`,
           icon: "chart", tier: tierByThresholds(phases.group, [1, 3, 5, 8, 12, 17]),
           desc: `Primero de su grupo en ${phases.group} de ${phases.entered} torneos` });
  }
  if (phases.wb > 0) {
    push({ id: "wbking", label: phases.wb === 1 ? "Ganó el cuadro alto" : `Cuadro Alto ×${phases.wb}`,
           icon: "trophy", tier: tierByThresholds(phases.wb, [1, 2, 4, 6, 9, 13]),
           desc: `Llegó a la final sin perder en ${phases.wb} torneo${phases.wb === 1 ? "" : "s"}` });
  }
  if (phases.lb > 0) {
    push({ id: "lbking", label: phases.lb === 1 ? "Sobrevivió abajo" : `Superviviente ×${phases.lb}`,
           icon: "flame", tier: tierByThresholds(phases.lb, [1, 2, 4, 6, 9, 13]),
           desc: `Ganó el cuadro de perdedores ${phases.lb} ${phases.lb === 1 ? "vez" : "veces"}` });
  }

  const roads = goldenRoadsFor(tournaments, teamName);
  if (roads.length > 0) {
    push({ id: "goldenroad", label: roads.length === 1 ? "Golden Road" : `Golden Road ×${roads.length}`,
           icon: "crown", tier: tierByThresholds(roads.length, [1, 2, 3, 4, 5, 6]),
           desc: `Los cuatro Kikudes de la Temporada ${roads.map((r) => r.season).join(", ")}` });
  }

  const slams = grandSlamsFor(tournaments, teamName);
  if (slams.length > 0) {
    push({ id: "grandslam", label: slams.length === 1 ? "Grand Slam" : `Grand Slam ×${slams.length}`,
           icon: "crown", tier: tierByThresholds(slams.length, [1, 2, 3, 4, 6, 8]),
           desc: `Torneo perfecto: grupo, cuadro de ganadores y final — ${slams.map((s) => s.kikudes || "?").join(", ")}` });
  }

  if (titles >= 1) {
    push({ id: "champion", label: titles === 1 ? "Campeón" : `Campeón ×${titles}`, icon: "trophy",
           tier: tierByThresholds(titles, [1, 2, 4, 6, 9, 13]),
           desc: `${titles} torneo${titles === 1 ? "" : "s"} ganado${titles === 1 ? "" : "s"}` });
  }
  if (seasonGolds >= 1) {
    push({ id: "season", label: seasonGolds === 1 ? "Campeón de Temporada" : `Temporadas ×${seasonGolds}`,
           icon: "crown", tier: tierByThresholds(seasonGolds, [1, 2, 3, 4, 6, 8]),
           desc: `${seasonGolds} temporada${seasonGolds === 1 ? "" : "s"} ganada${seasonGolds === 1 ? "" : "s"} por puntos` });
  }
  if (summit.reached) {
    push({ id: "summit", label: summit.isCurrent ? "Número Uno" : "Ex Número Uno", icon: "peak",
           tier: tierByThresholds(summit.total, [1, 2, 4, 7, 11, 16]),
           desc: `${summit.total} torneo${summit.total === 1 ? "" : "s"} en lo más alto del power ranking` });
  }
  if (summit.longest >= 3) {
    push({ id: "dynasty", label: "Dinastía", icon: "crown",
           tier: tierByThresholds(summit.longest, [3, 4, 6, 8, 11, 15]),
           desc: `${summit.longest} torneos seguidos como número uno` });
  }
  if (podiums >= 3) {
    push({ id: "regular", label: "Habitual del Podio", icon: "medal",
           tier: tierByThresholds(podiums, [3, 5, 8, 12, 17, 24]),
           desc: `${podiums} podios` });
  }
  if (rec.pj >= 15 && rec.winPct >= 45) {
    push({ id: "elite", label: "Registro de Élite", icon: "chart",
           tier: tierByThresholds(rec.winPct, [45, 50, 55, 60, 66, 72]),
           desc: `${Math.round(rec.winPct)}% de victorias en ${rec.pj} partidos` });
  }
  if (rec.bestStreak >= 3) {
    push({ id: "streak", label: "Imparable", icon: "flame",
           tier: tierByThresholds(rec.bestStreak, [3, 5, 7, 9, 12, 15]),
           desc: `${rec.bestStreak} victorias seguidas` });
  }
  if (rec.pj >= 8 && rec.cleanSheets / rec.pj >= 0.15) {
    const pctCS = (rec.cleanSheets / rec.pj) * 100;
    push({ id: "wall", label: "El Muro", icon: "shield",
           tier: tierByThresholds(pctCS, [15, 22, 30, 38, 46, 55]),
           desc: `Sin encajar en el ${Math.round(pctCS)}% de sus partidos` });
  }
  if (rec.pj >= 8 && rec.gfAvg >= 1.5) {
    push({ id: "goals", label: "Máquina de Goles", icon: "flame",
           tier: tierByThresholds(rec.gfAvg, [1.5, 1.9, 2.3, 2.7, 3.1, 3.6]),
           desc: `${rec.gfAvg.toFixed(2)} goles por partido` });
  }
  if (rec.pj >= 15) {
    push({ id: "veteran", label: "Veterano", icon: "clock",
           tier: tierByThresholds(rec.pj, [15, 35, 60, 100, 150, 220]),
           desc: `${rec.pj} partidos disputados` });
  }
  if (honours.tournamentPlaces.length === 0 && rec.pj >= 10) {
    push({ id: "nearly", label: "Aún Buscándolo", tone: "slate", icon: "clock",
           desc: "Todavía sin podio — por algo se empieza" });
  }
  return out;
}

function BadgeIcon({ icon, size = 13, color }) {
  const p = { size, style: { color } };
  if (icon === "trophy") return <Trophy {...p} />;
  if (icon === "star" || icon === "peak") return <Star {...p} fill={color} />;
  if (icon === "crown") return <Star {...p} fill={color} />;
  if (icon === "shield") return <Users {...p} />;
  if (icon === "medal") return <Trophy {...p} />;
  if (icon === "flame") return <Star {...p} />;
  if (icon === "chart") return <Check {...p} />;
  if (icon === "clock") return <Calendar {...p} />;
  if (icon === "moon") return <Calendar {...p} />;
  return <Star {...p} />;
}

function Badge({ badge, size = "md" }) {
  // El sello OG tiene su propio tratamiento: no es un logro deportivo y no debe parecerse
  // a las demás medallas.
  if (badge.og) {
    return (
      <div title={badge.desc}
           style={{ background: "#0B0B0C", borderColor: "#D4A017" }}
           className={`border rounded-sm inline-flex items-center gap-2 ${size === "md" ? "px-2.5 py-1.5" : "px-2 py-1"}`}>
        <OGMark size={size === "md" ? "md" : "sm"} />
        {size === "md" && badge.desc && (
          <span style={{ color: "#C9B77A", fontSize: "0.52rem" }} className="truncate">{badge.desc}</span>
        )}
      </div>
    );
  }
  // Si la medalla tiene nivel, el nivel manda sobre el color base: así se ve de un vistazo
  // quién tiene un Campeón de Bronce y quién uno de Diamante.
  const t = badge.tier;
  const tone = t
    ? { bg: t.glow, ring: t.color, fg: t.color }
    : (BADGE_TONES[badge.tone] || BADGE_TONES.slate);
  const big = size === "md";
  return (
    <div title={`${badge.label}${t ? ` · ${t.label}` : ""}${badge.desc ? ` — ${badge.desc}` : ""}`}
         style={{ background: tone.bg, borderColor: tone.ring, color: tone.fg,
                  boxShadow: t && (t.id === "legend" || t.id === "diamond") ? `0 0 0 1px ${t.color}44` : undefined }}
         className={`border rounded-sm inline-flex items-center gap-1.5 ${big ? "px-2.5 py-1.5" : "px-2 py-1"}`}>
      <BadgeIcon icon={badge.icon} size={big ? 14 : 11} color={tone.ring} />
      <div className="min-w-0">
        <div className="flex items-center gap-1.5">
          <span style={{ ...headingStyle, fontSize: big ? "0.65rem" : "0.55rem" }} className="truncate">
            {badge.label}
          </span>
          {t && (
            <span style={{ background: t.color, color: t.glow, ...headingStyle, fontSize: "0.45rem" }}
                  className="rounded-sm px-1 py-px shrink-0">
              {t.short}
            </span>
          )}
        </div>
        {big && badge.desc && (
          <div style={{ fontSize: "0.52rem", opacity: 0.75 }} className="truncate">{badge.desc}</div>
        )}
      </div>
    </div>
  );
}

function TeamBadges({ teamName, team, teams }) {
  const data = useRecordedData();
  const tournaments = data ? [...data.tournaments].sort((a, b) => tournamentOrderKey(a).localeCompare(tournamentOrderKey(b))) : [];
  const matches = data ? cachedMatches(data.tournaments, data.league, teams || [], data.leagues).matches : [];
  // los superlativos son comparativos, así que hay que mirar a todos los clubes a la vez
  const allClubs = Array.from(new Set([...(teams || []).map((t) => t.name), ...clubsWithSquads()]));
  const supers = data ? leagueSuperlatives(matches, allClubs)[teamName] || [] : [];
  const rank = { legend: 6, diamond: 5, platinum: 4, gold: 3, silver: 2, bronze: 1 };
  const badges = computeBadges(teamName, team, tournaments, matches, supers)
    // el sello OG siempre encabeza; el resto por nivel
    .sort((a, b) => (b.og ? 1 : 0) - (a.og ? 1 : 0)
                    || (rank[b.tier?.id] || 0) - (rank[a.tier?.id] || 0));

  if (badges.length === 0) {
    return (
      <div>
        <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }} className="mb-2">Medallas</h3>
        <p style={{ color: TOKENS.muted }} className="text-sm">None yet — badges are earned by playing.</p>
      </div>
    );
  }
  return (
    <div>
      <div className="flex items-center gap-2 mb-2 flex-wrap">
        <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }}>
          Medallas <span style={{ color: TOKENS.muted, fontSize: "0.62rem" }}>({badges.length})</span>
        </h3>
        {TIERS.filter((t) => badges.some((b) => b.tier?.id === t.id)).map((t) => (
          <span key={t.id} style={{ background: t.glow, color: t.color, ...headingStyle, fontSize: "0.5rem" }}
                className="rounded-sm px-1.5 py-0.5" title={t.label}>
            {badges.filter((b) => b.tier?.id === t.id).length} {t.label}
          </span>
        ))}
      </div>
      {(() => {
        const sup = badges.filter((b) => b.id.startsWith("sup-"));
        const own = badges.filter((b) => !b.id.startsWith("sup-") && !b.og);
        return (
          <>
            {(() => {
              const og = badges.find((b) => b.og);
              return og ? (
                <div className="mb-3">
                  <div style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted }} className="mb-1.5">
                    Club original
                  </div>
                  <Badge badge={og} />
                </div>
              ) : null;
            })()}

            {sup.length > 0 && (
              <div className="mb-3">
                <div style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted }} className="mb-1.5">
                  Lo mejor de la liga — nadie más tiene esto
                </div>
                <div className="flex flex-wrap gap-2">
                  {sup.map((b) => <Badge key={b.id} badge={b} />)}
                </div>
              </div>
            )}
            {own.length > 0 && (
              <div>
                {sup.length > 0 && (
                  <div style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted }} className="mb-1.5">
                    Logros del club
                  </div>
                )}
                <div className="flex flex-wrap gap-2">
                  {own.map((b) => <Badge key={b.id} badge={b} />)}
                </div>
              </div>
            )}
          </>
        );
      })()}
    </div>
  );
}

// A club's most-used players, shown as a squad rather than a table.
// ---- Logros de jugador ----
// Cualquier cosa basada en un promedio necesita un mínimo de partidos, o la lista la lidera
// quien jugó tres veces y tuvo suerte. Es el mismo criterio que ya se aplica a los clubes.
const PLAYER_MIN_APPS = 10;

const PLAYER_AWARDS = [
  { id: "legend",  label: "Leyenda",        icon: "crown", min: 60,
    test: (p) => p.a >= 60 && p.r >= 6.3,
    desc: (p) => `${p.a} partidos con ${p.r.toFixed(2)} de media` },
  { id: "elite",   label: "Nota de Élite",  icon: "star",  min: PLAYER_MIN_APPS,
    test: (p) => p.a >= PLAYER_MIN_APPS && p.r >= 6.5,
    desc: (p) => `${p.r.toFixed(2)} de media en ${p.a} partidos` },
  { id: "decisive", label: "Decisivo",      icon: "trophy", min: 15,
    test: (p) => p.a >= 15 && p.m / p.a >= 0.12,
    desc: (p) => `MVP en el ${Math.round((p.m / p.a) * 100)}% de sus partidos` },
  { id: "mvpking", label: "Rey del MVP",    icon: "trophy", min: 0,
    test: (p) => p.m >= 10,
    desc: (p) => `${p.m} MVPs` },
  { id: "iron",    label: "Inamovible",     icon: "clock",  min: 0,
    test: (p) => p.a >= 100,
    desc: (p) => `${p.a} partidos disputados` },
  { id: "peak",    label: "Techo Alto",     icon: "flame",  min: 0,
    // llegar a 9 con 300 partidos es estadística; hacerlo con 30 es talento
    test: (p) => p.b >= 9 && p.a <= 80,
    desc: (p) => `Llegó a ${p.b.toFixed(1)} en sólo ${p.a} partidos` },
  { id: "steady",  label: "Fiable",         icon: "shield", min: 20,
    test: (p) => p.a >= 20 && p.r >= 5.9 && p.r < 6.5,
    desc: (p) => `${p.r.toFixed(2)} sostenido en ${p.a} partidos` },
];

function playerAwards(p) {
  if (!p || p.a === 0) return [];
  return PLAYER_AWARDS.filter((a) => a.test(p)).map((a) => ({
    id: a.id, label: a.label, icon: a.icon, desc: a.desc(p),
    tier: tierByThresholds(
      a.id === "mvpking" ? p.m : a.id === "iron" ? p.a : a.id === "peak" ? p.b * 10 : p.r * 10,
      a.id === "mvpking" ? [10, 15, 22, 30, 40, 55]
      : a.id === "iron"  ? [100, 150, 220, 300, 400, 500]
      : a.id === "peak"  ? [90, 92, 94, 96, 98, 100]
      : [59, 61, 63, 65, 67, 70]
    ),
  }));
}

// El plantel histórico como tabla: quién ha jugado para el club, cuánto y con qué nota.
// Tres columnas numéricas alineadas se leen mucho mejor que barras y chips mezclados.
function TeamSquad({ teamName, teams }) {
  const [expanded, setExpanded] = useState(false);
  const [sort, setSort] = useState("apps");   // apps | rating | mvp
  const squad = squadFor(teamName);
  if (squad.length === 0) {
    return (
      <div className="mb-6">
        <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }} className="mb-2">Plantel histórico</h3>
        <p style={{ color: TOKENS.muted }} className="text-sm">Sin jugadores registrados para este club todavía.</p>
      </div>
    );
  }
  const total = squad.reduce((a, p) => a + p.forClub, 0);
  const sorted = [...squad].sort((a, b) =>
    sort === "rating" ? ((b.forClub >= 5 ? b.rHere : -1) - (a.forClub >= 5 ? a.rHere : -1)) || b.forClub - a.forClub
    : sort === "mvp" ? (b.mHere || 0) - (a.mHere || 0) || b.forClub - a.forClub
    : b.forClub - a.forClub);
  const LIMIT = 12;
  const rows = expanded ? sorted : sorted.slice(0, LIMIT);
  const maxApps = sorted[0]?.forClub || 1;
  const tone = (r) => (r >= 6.3 ? TOKENS.accent : r < 5.6 ? TOKENS.danger : TOKENS.ink);

  // resumen por línea, para ver de qué está hecho el plantel
  const byLine = {};
  squad.forEach((p) => { const k = p.p || "??"; byLine[k] = (byLine[k] || 0) + 1; });

  return (
    <div className="mb-6">
      <div className="flex items-center gap-2 mb-2 flex-wrap">
        <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }}>Plantel histórico</h3>
        <span style={{ color: TOKENS.muted }} className="text-xs">
          {squad.length} jugadores · {total} apariciones
        </span>
        {POSITION_ORDER.map((k) => byLine[k] && (
          <span key={k} style={{ background: POSITIONS[k].bg, color: POSITIONS[k].color, ...headingStyle, fontSize: "0.5rem" }}
                className="rounded-sm px-1.5 py-0.5">{byLine[k]} {POSITIONS[k].label}</span>
        ))}
        <span className="ml-auto flex gap-1">
          {[["apps", "Partidos"], ["rating", "Nota"], ["mvp", "MVP"]].map(([k, l]) => (
            <FilterPill key={k} active={sort === k} onClick={() => setSort(k)}>{l}</FilterPill>
          ))}
        </span>
      </div>

      <div style={{ background: TOKENS.surface, borderColor: TOKENS.line }} className="border rounded-sm overflow-hidden">
        <table className="w-full text-sm" style={{ borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: `1px solid ${TOKENS.line}` }}>
              {[["#", "w-8 text-center"], ["", "w-10"], ["Jugador", "text-left"], ["Partidos", "text-right"],
                ["Nota", "text-right"], ["MVP", "text-right pr-3"]].map(([h, cls]) => (
                <th key={h} style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted }}
                    className={`py-2 px-1.5 whitespace-nowrap ${cls}`}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((p, i) => {
              const few = p.forClub < 5;
              return (
                <tr key={p.n} style={{ borderBottom: `1px solid ${TOKENS.line}` }}>
                  <td className="py-1.5 px-1.5 text-center" style={{ color: TOKENS.muted, fontSize: "0.65rem" }}>{i + 1}</td>
                  <td className="py-1.5 px-1.5"><PosTag pos={p.p} size="sm" /></td>
                  <td className="py-1.5 px-1.5">
                    <div className="flex items-center gap-1.5 min-w-0">
                      <span style={{ ...headingStyle, fontSize: "0.72rem" }} className="truncate">{p.n}</span>
                      {i === 0 && sort === "apps" && <Star size={10} style={{ color: TOKENS.gold }} fill={TOKENS.gold} className="shrink-0" />}
                    </div>
                  </td>
                  <td className="py-1.5 px-1.5 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <div style={{ background: TOKENS.line, width: 56, height: 4 }} className="rounded-sm overflow-hidden hidden sm:block">
                        <div style={{ background: TOKENS.accent, width: `${(p.forClub / maxApps) * 100}%`, height: "100%" }} />
                      </div>
                      <span style={{ ...headingStyle, fontSize: "0.72rem", minWidth: 28 }} className="text-right">{p.forClub}</span>
                    </div>
                  </td>
                  <td className="py-1.5 px-1.5 text-right">
                    <span style={{ ...headingStyle, fontSize: "0.75rem", color: few ? TOKENS.muted : tone(p.rHere ?? p.r) }}
                          title={few ? "Pocos partidos para que la nota diga mucho" : `Global ${p.r.toFixed(2)}`}>
                      {(p.rHere ?? p.r).toFixed(2)}
                    </span>
                  </td>
                  <td className="py-1.5 px-1.5 pr-3 text-right">
                    {p.mHere > 0
                      ? <span style={{ ...headingStyle, color: TOKENS.gold, fontSize: "0.72rem" }}>{p.mHere}</span>
                      : <span style={{ color: TOKENS.line }}>–</span>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {squad.length > LIMIT && (
        <button onClick={() => setExpanded(!expanded)} style={{ color: TOKENS.accent }}
                className="text-xs font-bold uppercase tracking-wide mt-2">
          {expanded ? "Ver menos" : `Ver los ${squad.length}`}
        </button>
      )}
      <p style={{ color: TOKENS.muted }} className="text-xs mt-2">
        De las capturas de los partidos. Partidos y nota son de este club; la nota en gris es de jugadores con menos de 5.
      </p>
    </div>
  );
}

// ============ Impacto y sinergia ============
// c = [club, apariciones, nota media EN ese club, MVPs EN ese club]. Guardar la nota por
// club es lo que permite preguntar quién saca más de cada jugador, en vez de sólo quién
// lo usa más.
function clubRow(p, club) {
  const hit = (p.c || []).find((x) => x[0] === club);
  return hit ? { apps: hit[1], avg: hit[2], mvp: hit[3] } : null;
}

// KIKUDES IMPACT INDEX — 0..100.
// Tres cosas distintas hacen importante a un jugador, y ninguna basta sola:
//   nota      lo bien que juega
//   MVP       cuántas veces decide un partido
//   confianza cuánto lo usa el club (con rendimientos decrecientes: el 60º partido
//             dice menos que el 6º, así que va por raíz y no lineal)
// El peso se reparte 45/30/25. La nota se mide contra la media real del club, no contra
// un número inventado, así un plantel entero flojo no queda con impacto artificialmente bajo.
const IMPACT_WEIGHTS = { quality: 45, decisive: 30, trust: 25 };

function impactFor(p, club, ctx) {
  const row = clubRow(p, club);
  if (!row || row.apps < 4) return null;   // muestras minúsculas engañan más de lo que informan
  const q = Math.max(0, Math.min(1, (row.avg - ctx.floor) / Math.max(0.01, ctx.ceil - ctx.floor)));
  const mvpRate = row.mvp / row.apps;
  const d = Math.max(0, Math.min(1, mvpRate / Math.max(0.001, ctx.topMvpRate)));
  const t = Math.sqrt(row.apps) / Math.sqrt(Math.max(1, ctx.maxApps));
  // Con pocos partidos una nota alta puede ser suerte, así que el total se atenúa hasta
  // tener una muestra decente. A 12 partidos ya no penaliza.
  const confidence = Math.min(1, Math.sqrt(row.apps / 12));
  const score = (q * IMPACT_WEIGHTS.quality + d * IMPACT_WEIGHTS.decisive + t * IMPACT_WEIGHTS.trust) * confidence;
  return {
    ...row, score: Math.round(score), confidence,
    parts: { quality: q * IMPACT_WEIGHTS.quality, decisive: d * IMPACT_WEIGHTS.decisive, trust: t * IMPACT_WEIGHTS.trust },
    // sinergia: cuánto mejor (o peor) rinde aquí que en el resto de su carrera
    synergy: p.a > row.apps ? row.avg - (p.r * p.a - row.avg * row.apps) / (p.a - row.apps) : 0,
  };
}

function clubImpact(club) {
  const squad = PLAYER_DB.map((p) => ({ p, row: clubRow(p, club) })).filter((x) => x.row && x.row.apps >= 2);
  if (squad.length === 0) return { rows: [], ctx: null };
  const avgs = squad.map((x) => x.row.avg).sort((a, b) => a - b);
  const ctx = {
    floor: avgs[Math.floor(avgs.length * 0.1)] ?? avgs[0],
    ceil: avgs[Math.floor(avgs.length * 0.95)] ?? avgs[avgs.length - 1],
    maxApps: Math.max(...squad.map((x) => x.row.apps)),
    topMvpRate: Math.max(0.02, ...squad.map((x) => x.row.mvp / x.row.apps)),
  };
  const rows = squad
    .map((x) => ({ ...x.p, impact: impactFor(x.p, club, ctx) }))
    .filter((x) => x.impact)
    .sort((a, b) => b.impact.score - a.impact.score);
  return { rows, ctx };
}

// Para un jugador: en qué club rinde mejor.
function bestClubFor(p, minApps = 5) {
  const elig = (p.c || []).filter((c) => c[1] >= minApps);
  if (elig.length < 2) return null;
  const sorted = [...elig].sort((a, b) => b[2] - a[2]);
  return { best: sorted[0], worst: sorted[sorted.length - 1], spread: sorted[0][2] - sorted[sorted.length - 1][2] };
}

function ImpactBar({ parts, score }) {
  const w = (v) => `${(v / 100) * 100}%`;
  return (
    <div style={{ background: TOKENS.line, height: 6 }} className="rounded-sm overflow-hidden flex">
      <div style={{ background: TOKENS.accent, width: w(parts.quality) }} title="Nota" />
      <div style={{ background: TOKENS.gold, width: w(parts.decisive) }} title="MVPs" />
      <div style={{ background: "#1B5FA8", width: w(parts.trust) }} title="Confianza" />
    </div>
  );
}

function SquadImpact({ teams }) {
  const clubs = clubsWithSquads();
  const [club, setClub] = useState(clubs[0] || "");
  const [open, setOpen] = useState(null);
  const { rows, ctx } = club ? clubImpact(club) : { rows: [], ctx: null };
  const top = rows.slice(0, 3);
  const rest = rows.slice(3, 40);

  if (clubs.length === 0) {
    return <p style={{ color: TOKENS.muted }} className="text-sm">Sin datos de club todavía.</p>;
  }

  return (
    <div>
      <p style={{ color: TOKENS.muted }} className="text-sm mb-3">
        El <strong>Impact Index</strong> mezcla tres cosas: la nota que saca en ese club (45), cuántas veces fue MVP
        (30) y cuánto lo usan (25). La nota se compara contra el propio plantel, no contra un baremo externo.
      </p>

      <div className="flex flex-wrap gap-1.5 mb-4">
        {clubs.map((cn) => (
          <button key={cn} onClick={() => { setClub(cn); setOpen(null); }}
                  style={{ borderColor: club === cn ? TOKENS.gold : TOKENS.line,
                           background: club === cn ? `${TOKENS.gold}1A` : TOKENS.surface }}
                  className="border rounded-sm px-2 py-1 flex items-center gap-1.5">
            <TeamCrest name={cn} teams={teams} size={16} />
            <span style={{ ...headingStyle, fontSize: "0.62rem" }}>{cn}</span>
          </button>
        ))}
      </div>

      {/* podio de impacto */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 mb-4">
        {top.map((p, i) => (
          <div key={p.n} style={{ background: TOKENS.surface, borderColor: i === 0 ? TOKENS.gold : TOKENS.line }}
               className="border rounded-sm p-3">
            <div className="flex items-center gap-1.5 mb-1">
              <span style={{ ...pixelStyle, color: i === 0 ? TOKENS.gold : TOKENS.muted, fontSize: "1.1rem" }}>
                {i + 1}
              </span>
              <PosTag pos={p.p} size="sm" />
              <span style={{ ...headingStyle, fontSize: "0.75rem" }} className="truncate flex-1">{p.n}</span>
            </div>
            <div className="flex items-baseline gap-2">
              <span style={{ ...pixelStyle, fontSize: "1.6rem", color: i === 0 ? TOKENS.gold : TOKENS.ink }}>
                {p.impact.score}
              </span>
              <span style={{ color: TOKENS.muted, fontSize: "0.55rem" }}>impacto</span>
            </div>
            <ImpactBar parts={p.impact.parts} score={p.impact.score} />
            <div style={{ color: TOKENS.muted, fontSize: "0.55rem" }} className="mt-1">
              {p.impact.apps} partidos · nota {p.impact.avg.toFixed(2)}
              {p.impact.mvp > 0 ? ` · ★${p.impact.mvp}` : ""}
            </div>
          </div>
        ))}
      </div>

      {/* leyenda */}
      <div className="flex items-center gap-3 flex-wrap mb-2" style={{ fontSize: "0.55rem", color: TOKENS.muted }}>
        {[["Nota", TOKENS.accent], ["MVPs", TOKENS.gold], ["Confianza", "#1B5FA8"]].map(([l, c]) => (
          <span key={l} className="flex items-center gap-1">
            <span style={{ background: c, width: 10, height: 6 }} className="rounded-sm" /> {l}
          </span>
        ))}
      </div>

      <div style={{ background: TOKENS.surface, borderColor: TOKENS.line }} className="border rounded-sm overflow-hidden">
        {rest.map((p, i) => {
          const isOpen = open === p.n;
          const syn = p.impact.synergy;
          return (
            <div key={p.n} style={{ borderBottom: `1px solid ${TOKENS.line}` }}>
              <button onClick={() => setOpen(isOpen ? null : p.n)}
                      className="w-full px-3 py-2 flex items-center gap-2 text-left">
                <span style={{ ...headingStyle, color: TOKENS.muted, fontSize: "0.65rem", width: 22 }}
                      className="text-center shrink-0">{i + 4}</span>
                <PosTag pos={p.p} size="sm" />
                <span style={{ ...headingStyle, fontSize: "0.72rem" }} className="flex-1 min-w-0 truncate">{p.n}</span>
                <span style={{ color: TOKENS.muted, fontSize: "0.55rem", width: 48 }}
                      className="text-right shrink-0 whitespace-nowrap">{p.impact.apps}p</span>
                <span style={{ color: TOKENS.ink, fontSize: "0.62rem", width: 34 }}
                      className="text-right shrink-0">{p.impact.avg.toFixed(2)}</span>
                {Math.abs(syn) >= 0.15 && (
                  <span style={{ color: syn > 0 ? TOKENS.accent : TOKENS.danger, fontSize: "0.55rem", width: 40 }}
                        className="text-right shrink-0 whitespace-nowrap"
                        title="Diferencia con su nota en el resto de clubes">
                    {syn > 0 ? "▲" : "▼"}{Math.abs(syn).toFixed(2)}
                  </span>
                )}
                <span style={{ width: 70 }} className="shrink-0 hidden sm:block">
                  <ImpactBar parts={p.impact.parts} score={p.impact.score} />
                </span>
                <span style={{ ...headingStyle, color: TOKENS.gold, fontSize: "0.8rem", width: 28 }}
                      className="text-right shrink-0">{p.impact.score}</span>
              </button>
              {isOpen && (
                <div className="px-3 pb-2.5">
                  <div className="grid grid-cols-3 gap-px" style={{ background: TOKENS.line }}>
                    <Kpi label="Nota aquí" value={p.impact.avg.toFixed(2)}
                         sub={`global ${p.r.toFixed(2)}`} tone={p.impact.avg > p.r ? TOKENS.accent : undefined} />
                    <Kpi label="MVPs aquí" value={p.impact.mvp}
                         sub={p.impact.apps ? `${Math.round((p.impact.mvp / p.impact.apps) * 100)}% de sus partidos` : ""}
                         tone={p.impact.mvp ? TOKENS.gold : undefined} />
                    <Kpi label="Partidos aquí" value={p.impact.apps} sub={`de ${p.a} en total`} />
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
      {rows.length > 40 && (
        <p style={{ color: TOKENS.muted }} className="text-xs mt-2">Mostrando 40 de {rows.length}.</p>
      )}
    </div>
  );
}

function SynergyView({ teams }) {
  const [minApps, setMinApps] = useState(8);
  const rows = PLAYER_DB
    .map((p) => ({ p, s: bestClubFor(p, minApps) }))
    .filter((x) => x.s)
    .sort((a, b) => b.s.spread - a.s.spread)
    .slice(0, 30);

  return (
    <div>
      <p style={{ color: TOKENS.muted }} className="text-sm mb-3">
        El mismo jugador no rinde igual en todas partes. Aquí están las diferencias más grandes: en qué club saca su
        mejor nota y en cuál la peor, con al menos {minApps} partidos en cada uno para que no sea casualidad.
      </p>
      <div className="flex items-center gap-1.5 mb-4 flex-wrap">
        <span style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }}>Mínimo de partidos</span>
        {[5, 8, 12, 20].map((n) => (
          <FilterPill key={n} active={minApps === n} onClick={() => setMinApps(n)}>{n}</FilterPill>
        ))}
      </div>

      {rows.length === 0 ? (
        <p style={{ color: TOKENS.muted }} className="text-sm">Nadie tiene tantos partidos en dos clubes distintos.</p>
      ) : (
        <div className="space-y-2">
          {rows.map(({ p, s }) => (
            <div key={p.n} style={{ background: TOKENS.surface, borderColor: TOKENS.line }}
                 className="border rounded-sm px-3 py-2.5">
              <div className="flex items-center gap-2 mb-2">
                <PosTag pos={p.p} size="sm" />
                <span style={{ ...headingStyle, fontSize: "0.78rem" }} className="flex-1 min-w-0 truncate">{p.n}</span>
                <span style={{ ...headingStyle, color: TOKENS.gold, fontSize: "0.85rem" }}
                      title="Diferencia entre su mejor y su peor club">
                  {s.spread.toFixed(2)}
                </span>
                <span style={{ color: TOKENS.muted, fontSize: "0.5rem" }}>de diferencia</span>
              </div>
              <div className="flex items-stretch gap-2">
                <div style={{ background: "#D8F0E2", borderColor: "#1E7A4655" }}
                     className="border rounded-sm px-2 py-1.5 flex-1 min-w-0 flex items-center gap-1.5">
                  <TeamCrest name={s.best[0]} teams={teams} size={18} />
                  <span style={{ ...headingStyle, fontSize: "0.62rem", color: "#1E7A46" }} className="truncate flex-1">
                    {s.best[0]}
                  </span>
                  <span style={{ ...headingStyle, fontSize: "0.8rem", color: "#1E7A46" }}>{s.best[2].toFixed(2)}</span>
                  <span style={{ color: "#1E7A46", fontSize: "0.5rem", opacity: 0.8 }}>{s.best[1]}p</span>
                </div>
                <div style={{ background: "#F9DED9", borderColor: "#C0392B55" }}
                     className="border rounded-sm px-2 py-1.5 flex-1 min-w-0 flex items-center gap-1.5">
                  <TeamCrest name={s.worst[0]} teams={teams} size={18} />
                  <span style={{ ...headingStyle, fontSize: "0.62rem", color: "#C0392B" }} className="truncate flex-1">
                    {s.worst[0]}
                  </span>
                  <span style={{ ...headingStyle, fontSize: "0.8rem", color: "#C0392B" }}>{s.worst[2].toFixed(2)}</span>
                  <span style={{ color: "#C0392B", fontSize: "0.5rem", opacity: 0.8 }}>{s.worst[1]}p</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function PlayersPage({ teams }) {
  const [mode, setMode] = useState("list");
  const [q, setQ] = useState("");
  const [club, setClub] = useState("all");
  const [sort, setSort] = useState("a");
  const [minApps, setMinApps] = useState(PLAYER_MIN_APPS);
  const [openName, setOpenName] = useState(null);
  const clubs = clubsWithSquads();

  // the Players page reports on matches played, so catalogue-only entries are excluded
  let rows = PLAYER_DB.filter((p) => p.a > 0);
  // Un promedio con tres partidos no dice nada, así que ordenar por nota exige un mínimo.
  const avgSorts = ["r", "b"];
  if (avgSorts.includes(sort)) rows = rows.filter((p) => p.a >= minApps);
  if (club !== "all") {
    rows = rows.map((p) => {
      const hit = p.c.find((x) => x[0] === club);
      return hit ? { ...p, forClub: hit[1] } : null;
    }).filter(Boolean);
  }
  if (q.trim()) {
    const k = q.trim().toLowerCase();
    rows = rows.filter((p) => p.n.toLowerCase().includes(k));
  }
  rows = [...rows].sort((x, y) =>
    sort === "n" ? x.n.localeCompare(y.n)
    : sort === "club" ? (y.forClub || 0) - (x.forClub || 0)
    : (y[sort] || 0) - (x[sort] || 0));

  const shown = rows.slice(0, 120);
  const tone = (r) => (r >= 6.3 ? TOKENS.accent : r < 5.6 ? TOKENS.danger : TOKENS.ink);

  return (
    <div>
      <h2 style={{ ...headingStyle, fontSize: "1.1rem", color: TOKENS.accent }} className="mb-1">Jugadores</h2>
      <p style={{ color: TOKENS.muted }} className="text-sm mb-4">
        {PLAYER_DB.length} players read from match screenshots — how often each has been picked, how they rate,
        and which clubs use them.
      </p>

      <div className="flex flex-wrap gap-2 mb-5">
        <FilterPill active={mode === "list"} onClick={() => setMode("list")}>Todos los jugadores</FilterPill>
        <FilterPill active={mode === "impact"} onClick={() => setMode("impact")}>Impacto por equipo</FilterPill>
        <FilterPill active={mode === "synergy"} onClick={() => setMode("synergy")}>Sinergia jugador–club</FilterPill>
      </div>

      {mode === "impact" && <SquadImpact teams={teams} />}
      {mode === "synergy" && <SynergyView teams={teams} />}
      {mode === "list" && (
      <>

      {/* headline numbers for the whole pool */}
      {(() => {
        const played = PLAYER_DB.filter((p) => p.a > 0);
        const pool = club === "all"
          ? played.map((p) => ({ ...p, weight: p.a }))
          : played.map((p) => {
              const hit = p.c.find((x) => x[0] === club);
              return hit ? { ...p, weight: hit[1] } : null;
            }).filter(Boolean);
        const apps = pool.reduce((a, p) => a + p.weight, 0);
        const avg = apps ? pool.reduce((a, p) => a + p.r * p.weight, 0) / apps : 0;
        const mvps = pool.reduce((a, p) => a + (p.m || 0), 0);
        return (
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-px mb-4" style={{ background: TOKENS.line }}>
            <Kpi label={club === "all" ? "Players used" : `Used by ${club}`} value={pool.length}
                 sub={club === "all" ? `${PLAYER_DB.length} selectable` : ""} />
            <Kpi label="Appearances" value={apps} />
            <Kpi label={club === "all" ? "MVP awards" : "MVPs (all clubs)"} value={mvps} tone={TOKENS.gold} />
            <Kpi label="Average rating" value={avg.toFixed(2)} />
          </div>
        );
      })()}

      <div className="flex flex-wrap gap-2 mb-3">
        <FilterPill active={club === "all"} onClick={() => { setClub("all"); setSort("a"); }}>
          Consolidated — every player
        </FilterPill>
        <FilterPill active={club !== "all"} onClick={() => { if (club === "all") { setClub(clubs[0]); setSort("club"); } }}>
          By club
        </FilterPill>
      </div>

      {club !== "all" && (
        <div className="flex flex-wrap gap-1.5 mb-3">
          {clubs.map((cn) => (
            <button key={cn} onClick={() => setClub(cn)}
                    style={{ borderColor: club === cn ? TOKENS.gold : TOKENS.line,
                             background: club === cn ? `${TOKENS.gold}1A` : TOKENS.surface }}
                    className="border rounded-sm px-2 py-1 flex items-center gap-1.5">
              <TeamCrest name={cn} teams={teams} size={16} />
              <span style={{ ...headingStyle, fontSize: "0.62rem" }}>{cn}</span>
            </button>
          ))}
        </div>
      )}

      <div className="flex flex-wrap items-center gap-2 mb-3">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search player"
               style={{ borderColor: TOKENS.line, background: TOKENS.bg, color: TOKENS.ink }}
               className="border rounded px-2 py-1.5 text-sm outline-none flex-1" />
      </div>
      <div className="flex flex-wrap gap-1.5 mb-3">
        {club !== "all" && (
          <FilterPill active={sort === "club"} onClick={() => setSort("club")}>Más usados aquí</FilterPill>
        )}
        {[["a", club === "all" ? "Más usados" : "Más usados en total"], ["r", "Mejor promedio"],
          ["m", "Más MVPs"], ["b", "Mejor nota puntual"], ["n", "A–Z"]].map(([k, label]) => (
          <FilterPill key={k} active={sort === k} onClick={() => setSort(k)}>{label}</FilterPill>
        ))}
      </div>

      {["r", "b"].includes(sort) && (
        <div className="flex items-center gap-1.5 mb-3 flex-wrap">
          <span style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }}>
            Mínimo de partidos
          </span>
          {[1, 5, 10, 20, 40].map((n) => (
            <FilterPill key={n} active={minApps === n} onClick={() => setMinApps(n)}>{n}</FilterPill>
          ))}
          <span style={{ color: TOKENS.muted, fontSize: "0.55rem" }}>
            {minApps === 1 ? "sin filtro — sale cualquiera con suerte" : `${rows.length} jugadores cumplen`}
          </span>
        </div>
      )}

      <div style={{ background: TOKENS.surface, borderColor: TOKENS.line }} className="border rounded-sm overflow-hidden">
        <div style={{ borderBottom: `1px solid ${TOKENS.line}`, background: TOKENS.bg }}
             className="px-3 py-1.5 flex items-center gap-2">
          {[["#", 28, "center"], ["Player", null, "left"]].map(([l, w, al]) => (
            <span key={l} style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted, width: w || undefined }}
                  className={w ? `shrink-0 text-${al}` : "flex-1 min-w-0"}>{l}</span>
          ))}
          {club !== "all" && (
            <span style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted, width: 58 }}
                  className="shrink-0 text-right">Aquí</span>
          )}
          <span style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted, width: 128 }}
                className="hidden sm:block shrink-0">Club principal</span>
          <span style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted, width: 34 }}
                className="shrink-0 text-right">MVP</span>
          <span style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted, width: 62 }}
                className="shrink-0 text-right">Partidos</span>
          <span style={{ ...headingStyle, fontSize: "0.5rem", color: TOKENS.muted, width: 42 }}
                className="shrink-0 text-right">Media</span>
          <span style={{ width: 12 }} className="shrink-0" />
        </div>
        {shown.map((p, i) => {
          const open = openName === p.n;
          const top = p.c[0];
          return (
            <div key={p.n} style={{ borderBottom: `1px solid ${TOKENS.line}` }}>
              <button onClick={() => setOpenName(open ? null : p.n)}
                      className="w-full px-3 py-2 flex items-center gap-2 text-left">
                <span style={{ ...headingStyle, color: TOKENS.muted, fontSize: "0.7rem", width: 28 }}
                      className="text-center shrink-0">{i + 1}</span>
                <PosTag pos={p.p} size="sm" />
                <TierBadge tier={playerTier(p)} size="sm" />
                <span style={{ ...headingStyle, fontSize: "0.8rem" }} className="flex-1 min-w-0 truncate">{p.n}</span>

                {club !== "all" && (
                  <span style={{ color: TOKENS.muted, fontSize: "0.6rem", width: 58 }}
                        className="text-right shrink-0 whitespace-nowrap">{p.forClub} here</span>
                )}

                {/* main club — fixed box so every row's crest sits on the same line */}
                <span className="hidden sm:flex items-center gap-1.5 shrink-0" style={{ width: 128 }}>
                  {top ? (
                    <>
                      <TeamCrest name={top[0]} teams={teams} size={16} />
                      <span style={{ color: TOKENS.muted, fontSize: "0.6rem" }} className="truncate">{top[0]}</span>
                    </>
                  ) : null}
                </span>

                <span style={{ color: p.m > 0 ? TOKENS.gold : "transparent", fontSize: "0.6rem", width: 34 }}
                      className="shrink-0 flex items-center justify-end gap-0.5 whitespace-nowrap">
                  <Trophy size={10} /> {p.m > 0 ? p.m : ""}
                </span>

                <span style={{ color: TOKENS.muted, fontSize: "0.65rem", width: 62 }}
                      className="text-right shrink-0 whitespace-nowrap">{p.a} apps</span>

                <span style={{ ...headingStyle, color: tone(p.r), fontSize: "0.85rem", width: 42 }}
                      className="text-right shrink-0">{p.r.toFixed(2)}</span>

                <span style={{ color: TOKENS.muted, width: 12 }} className="text-sm shrink-0 text-center">
                  {open ? "−" : "+"}
                </span>
              </button>
              {open && (
                <div className="px-3 pb-3">
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-px mb-2" style={{ background: TOKENS.line }}>
                    <Kpi label="Appearances" value={p.a} />
                    <Kpi label="Average" value={p.r.toFixed(2)} tone={tone(p.r)} />
                    <Kpi label="Best rating" value={p.b.toFixed(1)} tone={TOKENS.gold} />
                    <Kpi label="MVP awards" value={p.m || 0} tone={p.m ? TOKENS.gold : undefined}
                         sub={p.m ? `${Math.round((p.m / p.a) * 100)}% of games` : ""} />
                  </div>
                  {(() => {
                    const aw = playerAwards(p);
                    if (aw.length === 0) return null;
                    return (
                      <div className="mb-2">
                        <div style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }} className="mb-1.5">
                          Logros
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                          {aw.map((a) => <Badge key={a.id} badge={a} size="sm" />)}
                        </div>
                      </div>
                    );
                  })()}
                  <div style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }} className="mb-1.5">
                    Clubes que lo usan
                  </div>
                  <div className="space-y-1">
                    {p.c.map(([cn, k, avg, mv]) => (
                      <div key={cn} className="flex items-center gap-2">
                        <TeamCrest name={cn} teams={teams} size={18} />
                        <span className="text-xs flex-1 truncate">{cn}</span>
                        {mv > 0 && (
                          <span style={{ color: TOKENS.gold, fontSize: "0.55rem" }} className="shrink-0">★{mv}</span>
                        )}
                        <span style={{ color: avg > p.r ? TOKENS.accent : avg < p.r ? TOKENS.danger : TOKENS.muted,
                                       fontSize: "0.62rem", width: 32 }}
                              className="text-right shrink-0" title={`Nota aquí vs ${p.r.toFixed(2)} global`}>
                          {avg.toFixed(2)}
                        </span>
                        <div style={{ background: TOKENS.line, height: 5, width: 90 }} className="rounded-sm overflow-hidden shrink-0">
                          <div style={{ background: TOKENS.accent, width: `${(k / p.c[0][1]) * 100}%`, height: "100%" }} />
                        </div>
                        <span style={{ color: TOKENS.muted, fontSize: "0.6rem", width: 26 }} className="text-right shrink-0">{k}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
      {rows.length > 120 && (
        <p style={{ color: TOKENS.muted }} className="text-xs mt-2">
          Showing 120 of {rows.length} — search or filter to narrow.
        </p>
      )}
      </>
      )}
    </div>
  );
}

// El plantel de liga del club dentro de su perfil: el draft más los traspasos, agrupado
// por línea. Lo mismo que muestra la pestaña Rosters, pero en su ficha.
function TeamLeagueRoster({ teamName, teams }) {
  const [draft, setDraft] = useState(null);
  const [trades, setTrades] = useState(null);

  useEffect(() => {
    (async () => {
      setDraft(await loadKey(DRAFT_KEY, emptyDraft(), true));
      setTrades(await loadKey(TRADES_KEY, [], true));
    })();
  }, []);

  if (draft === null || trades === null) return null;
  if (!LEAGUE_TEAM_NAMES.some((n) => n.trim().toLowerCase() === (teamName || "").trim().toLowerCase())) {
    return null;                                     // este club no juega la liga
  }

  const active = (trades || []).filter((t) => !t.void);
  const { squad, incoming } = squadAfterTrades(draft, teamName, active);
  if (squad.length === 0) return null;

  const inSet = new Set(incoming.map((x) => x.trim().toLowerCase()));
  const fp = (draft?.franchise?.[teamName] || "").trim();
  const byLine = {};
  squad.slice(0, LEAGUE_ROSTER_SIZE).forEach((p) => {
    const k = positionOf(p) || "??";
    (byLine[k] ||= []).push(p);
  });
  const lines = [...POSITION_ORDER.filter((k) => byLine[k]), ...(byLine["??"] ? ["??"] : [])];

  return (
    <div className="mb-6">
      <div className="flex items-center gap-2 mb-2 flex-wrap">
        <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }}>Plantel de liga</h3>
        <span style={{ ...headingStyle, fontSize: "0.6rem",
                       color: squad.length > LEAGUE_ROSTER_SIZE ? TOKENS.danger
                            : squad.length === LEAGUE_ROSTER_SIZE ? TOKENS.accent : TOKENS.muted }}>
          {squad.length}/{LEAGUE_ROSTER_SIZE}
        </span>
        {POSITION_ORDER.map((k) => byLine[k] && (
          <span key={k} style={{ background: POSITIONS[k].bg, color: POSITIONS[k].color,
                                 ...headingStyle, fontSize: "0.5rem" }}
                className="rounded-sm px-1.5 py-0.5">
            {byLine[k].length} {POSITIONS[k].label}
          </span>
        ))}
      </div>

      <div style={{ background: TOKENS.surface, borderColor: TOKENS.line }}
           className="border rounded-sm p-3 space-y-2">
        {lines.map((k) => (
          <div key={k} className="flex items-start gap-2">
            <span style={{ ...headingStyle, fontSize: "0.5rem",
                           color: k === "??" ? TOKENS.muted : POSITIONS[k].color, width: 34 }}
                  className="shrink-0 pt-1">
              {k === "??" ? "S/P" : POSITIONS[k].label}
            </span>
            <div className="flex flex-wrap gap-1.5 flex-1">
              {byLine[k].map((p) => {
                const isIn = inSet.has(p.trim().toLowerCase());
                const isFp = p === fp;
                return (
                  <span key={p}
                        style={{ background: isFp ? `${TOKENS.gold}18` : isIn ? "#D8F0E2" : TOKENS.bg,
                                 borderColor: isFp ? TOKENS.gold : isIn ? "#1E7A4655" : TOKENS.line }}
                        className="border rounded-sm px-1.5 py-0.5 inline-flex items-center gap-1">
                    {isFp && <Star size={9} style={{ color: TOKENS.gold }} fill={TOKENS.gold} />}
                    <span style={{ ...headingStyle, fontSize: "0.62rem",
                                   color: isIn ? "#1E7A46" : TOKENS.ink }}>{p}</span>
                  </span>
                );
              })}
            </div>
          </div>
        ))}
      </div>
      <p style={{ color: TOKENS.muted }} className="text-xs mt-1.5">
        Sale del draft y ya incluye los traspasos. Se edita en League → Pick &amp; Ban Draft y Trades &amp; Gambles.
      </p>
    </div>
  );
}

function TeamRankingSection({ teamName, teams }) {
  const data = useRecordedData();
  if (!data) return null;

  const { matches, ordered } = cachedMatches(data.tournaments, data.league, teams || [], data.leagues);
  const finished = ordered.filter((t) => cachedStandings(t).some((r) => r.pos));
  if (finished.length === 0) return null;

  const key = (teamName || "").trim().toLowerCase();
  const hist = historicalRanking(ordered, matches);
  const hIdx = hist.findIndex((r) => r.name.trim().toLowerCase() === key);
  const hRow = hIdx >= 0 ? hist[hIdx] : null;

  const { rows, window } = powerRankingNow(ordered);
  const pIdx = rows.findIndex((r) => r.name.trim().toLowerCase() === key);
  const pRow = pIdx >= 0 ? rows[pIdx] : null;

  const summit = powerSummits(ordered, teamName);
  const ord = (n) => `${n}º`;

  // la liga en curso: es un indicador en sí mismo, al lado del power ranking y del histórico
  const table = computeLeagueTable(data.league || {});
  const lIdx = table.findIndex((r) => r.name.trim().toLowerCase() === key && r.pj > 0);
  const lRow = lIdx >= 0 ? table[lIdx] : null;
  const inLeague = LEAGUE_TEAM_NAMES.some((n) => n.trim().toLowerCase() === key);
  const lTotal = LEAGUE_SCHEDULE.reduce((a, md) => a + md.fixtures.length, 0);
  const lPlayed = LEAGUE_SCHEDULE.flatMap((md) => md.fixtures).filter((f) => {
    const r = (data.league || {})[f.id];
    if (!r || r.bye) return false;
    if (r.wo) return true;
    return r.h !== "" && r.h !== undefined && r.a !== "" && r.a !== undefined;
  }).length;

  return (
    <div>
      <div className="flex items-center gap-2 mb-2 flex-wrap">
        <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }}>Ranking</h3>
        {(() => {
          const t = clubTier(teamName, ordered, matches);
          return t ? <TierBadge tier={t.tier} sub={`rating ${t.score}`} /> : null;
        })()}
      </div>
      <div className={`grid grid-cols-1 sm:grid-cols-2 ${inLeague ? "lg:grid-cols-3" : ""} gap-3 mb-3`}>
        {inLeague && (
          <div style={{ background: TOKENS.surface, borderColor: lIdx === 0 ? TOKENS.gold : TOKENS.line }}
               className="border rounded-sm p-3">
            <div style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }} className="mb-1">
              Liga en curso · {lPlayed}/{lTotal}
            </div>
            {lRow ? (
              <>
                <div className="flex items-baseline gap-2 flex-wrap">
                  <span style={{ ...pixelStyle, fontSize: "1.5rem", color: lIdx === 0 ? TOKENS.gold : TOKENS.ink }}>
                    {ord(lIdx + 1)}
                  </span>
                  <span style={{ color: TOKENS.muted }} className="text-xs">de {table.filter((r) => r.pj > 0).length}</span>
                  <span style={{ ...headingStyle, color: TOKENS.gold, fontSize: "0.9rem" }} className="ml-auto">
                    {lRow.pts} pts
                  </span>
                </div>
                <div className="flex items-center gap-2 mt-1.5">
                  <FormStrip form={lRow.form.slice(-5)} max={5} />
                  <span style={{ color: TOKENS.muted, fontSize: "0.58rem" }}>
                    {lRow.w}G · {lRow.d}E · {lRow.l}P · DG {lRow.gd > 0 ? `+${lRow.gd}` : lRow.gd}
                  </span>
                </div>
              </>
            ) : (
              <p style={{ color: TOKENS.muted }} className="text-xs">Sin partidos de liga todavía.</p>
            )}
          </div>
        )}
        <div style={{ background: TOKENS.surface, borderColor: pIdx === 0 ? TOKENS.gold : TOKENS.line }}
             className="border rounded-sm p-3">
          <div style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }} className="mb-1">
            Power ranking · últimos {window.length} proceso{window.length === 1 ? "" : "s"}
          </div>
          {pRow ? (
            <div className="flex items-baseline gap-2 flex-wrap">
              <span style={{ ...headingStyle, fontSize: "1.6rem", color: pIdx === 0 ? TOKENS.gold : TOKENS.ink }}>
                {ord(pRow.pos)}
              </span>
              <span style={{ color: TOKENS.muted }} className="text-xs">de {rows.length}</span>
              <span style={{ ...headingStyle, color: TOKENS.gold, fontSize: "0.9rem" }} className="ml-auto">
                {pRow.pts} pts
              </span>
            </div>
          ) : (
            <p style={{ color: TOKENS.muted }} className="text-sm">Not in the current window.</p>
          )}
          {pRow && pRow.move !== null && pRow.move !== 0 && (
            <div style={{ color: pRow.move > 0 ? TOKENS.accent : TOKENS.danger }} className="text-xs mt-1">
              {pRow.move > 0 ? `▲ up ${pRow.move}` : `▼ down ${Math.abs(pRow.move)}`} since the last tournament
            </div>
          )}
        </div>

        <div style={{ background: TOKENS.surface, borderColor: hIdx === 0 ? TOKENS.gold : TOKENS.line }}
             className="border rounded-sm p-3">
          <div style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }} className="mb-1">
            Ranking histórico
          </div>
          {hRow ? (
            <>
              <div className="flex items-baseline gap-2 flex-wrap">
                <span style={{ ...headingStyle, fontSize: "1.6rem", color: hIdx === 0 ? TOKENS.gold : TOKENS.ink }}>
                  {ord(hIdx + 1)}
                </span>
                <span style={{ color: TOKENS.muted }} className="text-xs">de {hist.length}</span>
                <span style={{ ...headingStyle, color: TOKENS.gold, fontSize: "0.9rem" }} className="ml-auto">
                  {Math.round(hRow.score)} rating
                </span>
              </div>
              <div style={{ background: TOKENS.line, height: 5 }} className="rounded-sm overflow-hidden mt-2">
                <div style={{ background: hIdx === 0 ? TOKENS.gold : TOKENS.accent,
                              width: `${(hRow.score / (hist[0].score || 1)) * 100}%`, height: "100%" }} />
              </div>
            </>
          ) : (
            <p style={{ color: TOKENS.muted }} className="text-sm">No ranked record yet.</p>
          )}
        </div>
      </div>

    </div>
  );
}

function TeamStatsSection({ teamName, teams }) {
  const data = useRecordedData();
  if (!data) return <p style={{ color: TOKENS.muted }} className="text-sm">Cargando estadísticas…</p>;

  const stats = collectStats(data.tournaments, data.league, teams || []);
  const find = (rows) => rows.find((r) => r.name.trim().toLowerCase() === (teamName || "").trim().toLowerCase());
  const parts = [
    ["Group stage", find(stats.groups)],
    ["Winners bracket", find(stats.wb)],
    ["Losers bracket", find(stats.lb)],
    ["Grand finals", find(stats.gf)],
    ["League", find(stats.league)],
  ].filter(([, r]) => r);

  if (parts.length === 0) {
    return (
      <div>
        <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }} className="mb-2">Registrar</h3>
        <p style={{ color: TOKENS.muted }} className="text-sm">No matches recorded for this club yet.</p>
      </div>
    );
  }

  const all = parts.reduce((a, [, r]) => ({
    pj: a.pj + r.pj, w: a.w + r.w, d: a.d + r.d, l: a.l + r.l, gf: a.gf + r.gf, gc: a.gc + r.gc,
  }), { pj: 0, w: 0, d: 0, l: 0, gf: 0, gc: 0 });

  return (
    <div>
      <h3 style={{ ...headingStyle, fontSize: "0.8rem", color: TOKENS.accent }} className="mb-2">Registrar</h3>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-px mb-3" style={{ background: TOKENS.line }}>
        {[
          ["Played", all.pj],
          ["W · D · L", `${all.w} · ${all.d} · ${all.l}`],
          ["Goals", `${all.gf} : ${all.gc}`],
          ["Win rate", all.pj ? `${Math.round((all.w / all.pj) * 100)}%` : "—"],
        ].map(([label, value]) => (
          <div key={label} style={{ background: TOKENS.surface }} className="px-3 py-2.5">
            <div style={{ ...headingStyle, fontSize: "0.58rem", color: TOKENS.muted }}>{label}</div>
            <div style={{ ...headingStyle, fontSize: "1rem" }} className="mt-0.5">{value}</div>
          </div>
        ))}
      </div>
      <div style={{ background: TOKENS.surface, borderColor: TOKENS.line }} className="border rounded-sm overflow-x-auto">
        <table className="w-full text-sm" style={{ borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: `1px solid ${TOKENS.line}` }}>
              {["Phase", "PJ", "W", "D", "L", "GF", "GC", "Win %"].map((h) => (
                <th key={h} style={{ ...headingStyle, fontSize: "0.55rem", color: TOKENS.muted }}
                    className={`py-1.5 ${h === "Phase" ? "text-left pl-4" : "text-center"}`}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {parts.map(([label, r]) => (
              <tr key={label} style={{ borderBottom: `1px solid ${TOKENS.line}` }}>
                <td style={{ ...headingStyle, fontSize: "0.72rem" }} className="py-1.5 pl-4 whitespace-nowrap">{label}</td>
                <td className="py-1.5 text-center">{r.pj}</td>
                <td className="py-1.5 text-center">{r.w}</td>
                <td className="py-1.5 text-center">{r.d}</td>
                <td className="py-1.5 text-center">{r.l}</td>
                <td className="py-1.5 text-center">{r.gf}</td>
                <td className="py-1.5 text-center">{r.gc}</td>
                <td className="py-1.5 text-center">{Math.round(r.winPct)}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p style={{ color: TOKENS.muted }} className="text-xs mt-2">
        From results recorded in tournaments and the league.
      </p>
    </div>
  );
}

function TeamDetail({ team, teams, unlocked, onBack, onSave, onDelete, onSwitch }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(team);
  const [newTrophy, setNewTrophy] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(false);
  const heroInk = readableOn(draft.crestColor);

  useEffect(() => {
    setDraft(team);
    setEditing(false);
    setConfirmDelete(false);
  }, [team.id]);

  function field(key, value) {
    setDraft({ ...draft, [key]: value });
  }

  function addTrophy() {
    if (!newTrophy.trim()) return;
    setDraft({ ...draft, trophies: [...(draft.trophies || []), newTrophy.trim()] });
    setNewTrophy("");
  }

  function removeTrophy(i) {
    setDraft({ ...draft, trophies: draft.trophies.filter((_, idx) => idx !== i) });
  }

  return (
    <div>
      <div className="flex items-center gap-3 mb-5 flex-wrap">
        <button onClick={onBack} style={{ color: TOKENS.muted }}
                className="flex items-center gap-1 text-xs font-bold uppercase tracking-wide hover:opacity-70 shrink-0">
          <ChevronLeft size={14} /> Volver a la lista
        </button>
        {/* saltar de un club a otro sin volver a la lista: los activos primero */}
        <div className="flex items-center gap-1.5 flex-wrap flex-1">
          {[...teams]
            .sort((a, b) => (b.active === false ? 0 : 1) - (a.active === false ? 0 : 1))
            .map((t) => {
              const me = t.id === team.id;
              return (
                <button key={t.id} onClick={() => !me && onSwitch && onSwitch(t.id)} title={t.name}
                        style={{ borderColor: me ? TOKENS.gold : TOKENS.line,
                                 background: me ? `${TOKENS.gold}22` : TOKENS.surface,
                                 opacity: t.active === false && !me ? 0.45 : 1,
                                 cursor: me ? "default" : "pointer" }}
                        className="border rounded-sm p-1 shrink-0">
                  <TeamCrest name={t.name} teams={teams} size={26} />
                </button>
              );
            })}
        </div>
      </div>

      <div style={{ background: TOKENS.surface, borderColor: TOKENS.line }} className="border rounded-md overflow-hidden">
        <div style={{ background: draft.crestColor }} className="relative px-6 py-8">
          {/* heroInk flips with the plate so DVP's white badge stays readable */}
          {!draft.crest && (
            <div
              style={{
                position: "absolute", inset: 0, opacity: 0.15,
                backgroundImage: "repeating-linear-gradient(45deg, #fff 0px, #fff 1px, transparent 1px, transparent 14px)",
              }}
            />
          )}
          <div className="relative flex items-center gap-4">
            {draft.crest ? (
              <img src={draft.crest} alt={`${draft.name} crest`} className="w-20 h-20 object-contain shrink-0" />
            ) : (
              <div style={{ background: `${heroInk}22`, color: heroInk, borderColor: `${heroInk}66`, ...headingStyle }} className="w-16 h-16 rounded-full flex items-center justify-center text-xl shrink-0 border-2">
                {initials(draft.name)}
              </div>
            )}
            <div className="min-w-0 flex-1">
              {editing ? (
                <input
                  value={draft.name}
                  onChange={(e) => field("name", e.target.value)}
                  style={{ ...pixelStyle, background: `${heroInk}22`, color: heroInk }}
                  className="text-2xl px-2 py-1 rounded w-full outline-none"
                />
              ) : (
                <h2 style={{ ...pixelStyle, color: heroInk, fontSize: "1.75rem" }}>{draft.name}</h2>
              )}
            </div>
            {unlocked && !editing && (
              <button onClick={() => setEditing(true)} style={{ background: `${heroInk}22`, color: heroInk }} className="p-2 rounded shrink-0">
                <Pencil size={15} />
              </button>
            )}
          </div>
        </div>

        <div className="grid grid-cols-1 gap-px" style={{ background: TOKENS.line }}>
          <StatBlock
            label="Estado"
            value={
              editing ? (
                <label className="flex items-center gap-1.5 cursor-pointer">
                  <input type="checkbox" checked={draft.active !== false} onChange={(e) => field("active", e.target.checked)} />
                  Club activo
                </label>
              ) : (
                <span style={{ color: draft.active === false ? TOKENS.muted : TOKENS.accent }}>
                  {draft.active === false ? "Inactivo" : "Activo"}
                </span>
              )
            }
          />
        </div>

        <div className="p-6 space-y-6">
          <TeamBadges teamName={draft.name} team={draft} teams={teams} />

          <div>
            <TrophyCabinet
              teamName={draft.name}
              manual={draft.trophies}
              editing={editing}
              onRemove={removeTrophy}
            />
            {editing && (
              <div className="flex gap-2 mt-3">
                <input
                  value={newTrophy}
                  onChange={(e) => setNewTrophy(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && addTrophy()}
                  placeholder="e.g. Season 4 Champion"
                  style={{ borderColor: TOKENS.line, background: TOKENS.bg, color: TOKENS.ink }}
                  className="flex-1 border rounded px-3 py-1.5 text-sm outline-none"
                />
                <button onClick={addTrophy} style={{ background: TOKENS.gold, color: TOKENS.onGold }} className="px-3 rounded text-xs font-bold uppercase">
                  Add
                </button>
              </div>
            )}
          </div>

          <TeamLeagueRoster teamName={draft.name} teams={teams} />

          <TeamSquad teamName={draft.name} teams={teams} />

          <TeamRankingSection teamName={draft.name} teams={teams} />

          <TeamStatsSection teamName={draft.name} teams={teams} />

          {editing && (
            <div className="flex items-center justify-between pt-2 border-t gap-3 flex-wrap" style={{ borderColor: TOKENS.line }}>
              {confirmDelete ? (
                <div className="flex items-center gap-2">
                  <span style={{ color: TOKENS.muted }} className="text-xs">Remove {draft.name}?</span>
                  <button onClick={onDelete} style={{ background: TOKENS.danger, color: "#fff" }} className="text-xs font-bold uppercase tracking-wide px-2 py-1 rounded">
                    Yes, remove
                  </button>
                  <button onClick={() => setConfirmDelete(false)} style={{ color: TOKENS.muted }} className="text-xs font-bold uppercase tracking-wide px-2 py-1">
                    Cancel
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setConfirmDelete(true)}
                  style={{ color: TOKENS.danger }}
                  className="text-xs font-bold uppercase tracking-wide"
                >
                  Remove team
                </button>
              )}
              <div className="flex gap-2">
                <button
                  onClick={() => { setDraft(team); setEditing(false); }}
                  style={{ color: TOKENS.muted }}
                  className="text-xs font-bold uppercase tracking-wide px-3 py-2"
                >
                  Cancel
                </button>
                <button
                  onClick={() => { onSave(draft); setEditing(false); }}
                  style={{ background: TOKENS.gold, color: TOKENS.onGold }}
                  className="text-xs font-bold uppercase tracking-wide px-4 py-2 rounded"
                >
                  Save team
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function StatBlock({ label, value }) {
  return (
    <div style={{ background: TOKENS.surface }} className="px-5 py-3">
      <div style={{ ...headingStyle, fontSize: "0.65rem", color: TOKENS.muted }}>{label}</div>
      <div className="text-sm mt-0.5">{value}</div>
    </div>
  );
}
